//! Offline one-time invitation approval. No publicly reachable enrollment API.
//! Private client keys are generated by clients; this issuer only accepts signed CSRs.
use rand::{rngs::OsRng, RngCore};
use rcgen::{
    CertificateParams, CertificateSigningRequestParams, DnType, ExtendedKeyUsagePurpose, IsCa,
    Issuer, KeyPair, KeyUsagePurpose, SerialNumber,
};
use rusqlite::{params, Connection, OptionalExtension, TransactionBehavior};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::{
    env,
    error::Error,
    fs::{self, DirBuilder, File, OpenOptions},
    io::{BufReader, Read, Write},
    os::unix::fs::{DirBuilderExt, OpenOptionsExt, PermissionsExt},
    path::{Path, PathBuf},
    time::{Duration, SystemTime, UNIX_EPOCH},
};
use subtle::ConstantTimeEq;
use time::OffsetDateTime;

type Result<T> = std::result::Result<T, Box<dyn Error>>;
const LIMIT: u64 = 64 * 1024;
const VERSION: u32 = 1;
const DB_FILE: &str = "state.sqlite3";

#[derive(Serialize, Deserialize, Clone)]
#[serde(deny_unknown_fields)]
struct Invite {
    version: u32,
    id: String,
    token: String,
    device: String,
    expires_at: i64,
    server_name: String,
    ca_sha256: String,
    ca_pem: String,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Request {
    version: u32,
    id: String,
    token: String,
    device: String,
    server_name: String,
    ca_sha256: String,
    csr_pem: String,
}

struct Record {
    token_digest: Vec<u8>,
    device: String,
    expires_at: i64,
    server_name: String,
    ca_sha256: String,
    issued: Option<String>,
}

fn now() -> Result<i64> {
    Ok(SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs() as i64)
}
fn random<const N: usize>() -> [u8; N] {
    let mut bytes = [0u8; N];
    OsRng.fill_bytes(&mut bytes);
    bytes
}
fn digest(bytes: &[u8]) -> Vec<u8> {
    Sha256::digest(bytes).to_vec()
}
fn valid_device(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 48
        && value
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'-' | b'_'))
}
fn hex_bytes(value: &str, bytes: usize) -> bool {
    value.len() == 2 * bytes && value.bytes().all(|b| b.is_ascii_hexdigit())
}
fn read_text(path: &Path) -> Result<String> {
    let meta = fs::symlink_metadata(path)?;
    if !meta.is_file() || meta.file_type().is_symlink() || meta.len() > LIMIT {
        return Err("expected a regular, non-symlink file of at most 64 KiB".into());
    }
    let mut text = String::new();
    File::open(path)?
        .take(LIMIT + 1)
        .read_to_string(&mut text)?;
    if text.len() as u64 > LIMIT {
        return Err("file too large".into());
    }
    Ok(text)
}
fn create_file(path: &Path, text: &str) -> Result<()> {
    if text.len() as u64 > LIMIT {
        return Err("file too large".into());
    }
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(path)?;
    if let Err(error) = file
        .write_all(text.as_bytes())
        .and_then(|_| file.sync_all())
    {
        let _ = fs::remove_file(path);
        return Err(error.into());
    }
    Ok(())
}
fn ca_hash(pem: &str) -> Result<String> {
    let mut reader = BufReader::new(pem.as_bytes());
    let certs = rustls_pemfile::certs(&mut reader).collect::<std::io::Result<Vec<_>>>()?;
    if certs.len() != 1 {
        return Err("CA must contain exactly one PEM certificate".into());
    }
    Ok(hex::encode(digest(certs[0].as_ref())))
}
fn state_path(dir: &Path) -> Result<PathBuf> {
    let meta = fs::symlink_metadata(dir)?;
    if !meta.is_dir() || meta.file_type().is_symlink() || meta.permissions().mode() & 0o077 != 0 {
        return Err("state directory must be a private regular directory (0700)".into());
    }
    let path = dir.join(DB_FILE);
    let db = fs::symlink_metadata(&path)?;
    if !db.is_file() || db.file_type().is_symlink() || db.permissions().mode() & 0o077 != 0 {
        return Err("database must be an ordinary private file (0600)".into());
    }
    Ok(path)
}
fn connection(dir: &Path) -> Result<Connection> {
    let db = Connection::open_with_flags(
        state_path(dir)?,
        rusqlite::OpenFlags::SQLITE_OPEN_READ_WRITE,
    )?;
    db.busy_timeout(Duration::from_secs(10))?;
    Ok(db)
}
fn init(dir: &Path) -> Result<()> {
    let mut builder = DirBuilder::new();
    builder.mode(0o700);
    builder.create(dir)?;
    OpenOptions::new()
        .write(true)
        .create_new(true)
        .mode(0o600)
        .open(dir.join(DB_FILE))?;
    let db = connection(dir)?;
    db.execute_batch(
        "CREATE TABLE invitations (
      id TEXT PRIMARY KEY,
      token_sha256 BLOB NOT NULL,
      device TEXT NOT NULL,
      expires_at INTEGER NOT NULL,
      server_name TEXT NOT NULL,
      ca_sha256 TEXT NOT NULL,
      certificate TEXT
    );",
    )?;
    Ok(())
}
fn verify_invite(invite: &Invite) -> Result<()> {
    if invite.version != VERSION
        || !valid_device(&invite.device)
        || !hex_bytes(&invite.id, 16)
        || !hex_bytes(&invite.token, 32)
        || !hex_bytes(&invite.ca_sha256, 32)
        || invite.server_name.is_empty()
        || invite.ca_sha256 != ca_hash(&invite.ca_pem)?
    {
        return Err("invalid invitation or CA identity".into());
    }
    if now()? >= invite.expires_at {
        return Err("expired invitation".into());
    }
    Ok(())
}
fn invite(
    dir: &Path,
    device: &str,
    ttl: i64,
    ca: &Path,
    server: &str,
    out: &Path,
) -> Result<String> {
    if !valid_device(device)
        || !(1..=86400).contains(&ttl)
        || server.is_empty()
        || server.len() > 253
        || !server
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
    {
        return Err("invalid device, TTL or server DNS name".into());
    }
    let ca_pem = read_text(ca)?;
    let item = Invite {
        version: VERSION,
        id: hex::encode(random::<16>()),
        token: hex::encode(random::<32>()),
        device: device.to_string(),
        expires_at: now()?.checked_add(ttl).ok_or("timestamp overflow")?,
        server_name: server.to_string(),
        ca_sha256: ca_hash(&ca_pem)?,
        ca_pem,
    };
    let mut db = connection(dir)?;
    let tx = db.transaction_with_behavior(TransactionBehavior::Immediate)?;
    tx.execute(
        "INSERT INTO invitations(id, token_sha256, device, expires_at, server_name, ca_sha256)
        VALUES (?1,?2,?3,?4,?5,?6)",
        params![
            item.id,
            digest(item.token.as_bytes()),
            item.device,
            item.expires_at,
            item.server_name,
            item.ca_sha256
        ],
    )?;
    create_file(out, &serde_json::to_string_pretty(&item)?)?;
    tx.commit()?;
    Ok(item.id)
}
fn request(inv_path: &Path, csr_path: &Path, out: &Path) -> Result<()> {
    let inv: Invite = serde_json::from_str(&read_text(inv_path)?)?;
    verify_invite(&inv)?;
    let csr = read_text(csr_path)?;
    if csr.len() > 16384 {
        return Err("CSR too large".into());
    }
    // rcgen validates the CSR signature, proving possession of its private key.
    CertificateSigningRequestParams::from_pem(&csr)?;
    let req = Request {
        version: VERSION,
        id: inv.id,
        token: inv.token,
        device: inv.device,
        server_name: inv.server_name,
        ca_sha256: inv.ca_sha256,
        csr_pem: csr,
    };
    create_file(out, &serde_json::to_string_pretty(&req)?)
}
fn record(tx: &rusqlite::Transaction<'_>, id: &str) -> Result<Record> {
    Ok(tx
        .query_row(
            "SELECT token_sha256,device,expires_at,server_name,ca_sha256,certificate
         FROM invitations WHERE id=?1",
            [id],
            |row| {
                Ok(Record {
                    token_digest: row.get(0)?,
                    device: row.get(1)?,
                    expires_at: row.get(2)?,
                    server_name: row.get(3)?,
                    ca_sha256: row.get(4)?,
                    issued: row.get(5)?,
                })
            },
        )
        .optional()?
        .ok_or("invitation not found")?)
}
fn issue(csr_pem: &str, ca_cert: &str, ca_key: &str, device: &str) -> Result<String> {
    let csr = CertificateSigningRequestParams::from_pem(csr_pem)?;
    let issuer = Issuer::from_ca_cert_pem(ca_cert, KeyPair::from_pem(ca_key)?)?;
    let mut params = CertificateParams::new(Vec::<String>::new())?;
    params
        .distinguished_name
        .push(DnType::CommonName, format!("fedup-{device}"));
    params.is_ca = IsCa::ExplicitNoCa;
    params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
    params.extended_key_usages = vec![ExtendedKeyUsagePurpose::ClientAuth];
    let stamp = now()?;
    params.not_before = OffsetDateTime::from_unix_timestamp(stamp - 300)?;
    params.not_after = OffsetDateTime::from_unix_timestamp(stamp + 90 * 86400)?;
    let mut serial = random::<16>();
    serial[0] = (serial[0] & 0x7f) | 1;
    params.serial_number = Some(SerialNumber::from_slice(&serial));
    // CSR extensions and subject are NOT copied: certificate policy comes from operator.
    Ok(params.signed_by(&csr.public_key, &issuer)?.pem())
}
fn approve(dir: &Path, ca_cert: &Path, ca_key: &Path, req_file: &Path, out: &Path) -> Result<()> {
    let req: Request = serde_json::from_str(&read_text(req_file)?)?;
    if req.version != VERSION
        || !hex_bytes(&req.id, 16)
        || !hex_bytes(&req.token, 32)
        || !valid_device(&req.device)
        || req.csr_pem.len() > 16384
    {
        return Err("invalid request".into());
    }
    let ca = read_text(ca_cert)?;
    if req.ca_sha256 != ca_hash(&ca)? {
        return Err("issuer CA does not match request pin".into());
    }
    let mut db = connection(dir)?;
    let tx = db.transaction_with_behavior(TransactionBehavior::Immediate)?;
    let saved = record(&tx, &req.id)?;
    if saved.issued.is_some() {
        return Err("invitation consumed; use recover".into());
    }
    if now()? >= saved.expires_at {
        return Err("invitation expired on issuer".into());
    }
    if saved.device != req.device
        || saved.server_name != req.server_name
        || saved.ca_sha256 != req.ca_sha256
        || saved.token_digest.len() != 32
    {
        return Err("invitation metadata mismatch".into());
    }
    let supplied = digest(req.token.as_bytes());
    if !bool::from(saved.token_digest.as_slice().ct_eq(supplied.as_slice())) {
        return Err("invalid invitation token".into());
    }
    let cert = issue(&req.csr_pem, &ca, &read_text(ca_key)?, &saved.device)?;
    let changed = tx.execute(
        "UPDATE invitations SET certificate=?1 WHERE id=?2 AND certificate IS NULL",
        params![cert, req.id],
    )?;
    if changed != 1 {
        return Err("invitation already used".into());
    }
    tx.commit()?; // Consume before export. Recovery only exports the SAME cert.
    create_file(out, &cert)
}
fn recover(dir: &Path, id: &str, out: &Path) -> Result<()> {
    if !hex_bytes(id, 16) {
        return Err("invalid invitation ID".into());
    }
    let db = connection(dir)?;
    let issued: Option<String> = db
        .query_row(
            "SELECT certificate FROM invitations WHERE id=?1",
            [id],
            |row| row.get(0),
        )
        .optional()?
        .flatten();
    create_file(out, &issued.ok_or("no issued certificate exists")?)
}
fn usage() {
    eprintln!(
        "FedUp OFFLINE enrollment, experimental:\n\
      fedup-enroll init <private-state-dir>\n\
      fedup-enroll invite <state-dir> <device> <ttl-seconds> <ca.pem> <server-dns> <invite.json>\n\
      fedup-enroll request <invite.json> <client.csr.pem> <request.json>\n\
      fedup-enroll approve <state-dir> <ca.pem> <OFFLINE-ca.key> <request.json> <cert.pem>\n\
      fedup-enroll recover <state-dir> <invitation-id> <cert.pem>\n\
      This program never generates, receives or stores CLIENT private keys."
    );
}
fn run() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    match args.as_slice() {
        [_, action, dir] if action == "init" => init(Path::new(dir)),
        [_, action, dir, device, ttl, ca, server, out] if action == "invite" => {
            let id = invite(
                Path::new(dir),
                device,
                ttl.parse()?,
                Path::new(ca),
                server,
                Path::new(out),
            )?;
            println!("Created invitation {id} (secret not printed)");
            Ok(())
        }
        [_, action, inv, csr, out] if action == "request" => {
            request(Path::new(inv), Path::new(csr), Path::new(out))
        }
        [_, action, dir, ca, key, req, out] if action == "approve" => approve(
            Path::new(dir),
            Path::new(ca),
            Path::new(key),
            Path::new(req),
            Path::new(out),
        ),
        [_, action, dir, id, out] if action == "recover" => {
            recover(Path::new(dir), id, Path::new(out))
        }
        _ => {
            usage();
            Err("invalid arguments".into())
        }
    }
}
fn main() {
    if let Err(error) = run() {
        eprintln!("fedup-enroll: {error}");
        std::process::exit(1);
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use rcgen::BasicConstraints;
    fn setup() -> (tempfile::TempDir, PathBuf, PathBuf, PathBuf) {
        let temp = tempfile::tempdir().unwrap();
        let db = temp.path().join("state");
        init(&db).unwrap();
        let ca_key = KeyPair::generate().unwrap();
        let mut params = CertificateParams::new(Vec::<String>::new()).unwrap();
        params
            .distinguished_name
            .push(DnType::CommonName, "Test FedUp CA");
        params.is_ca = IsCa::Ca(BasicConstraints::Constrained(0));
        params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
        let ca_cert = params.self_signed(&ca_key).unwrap();
        let ca = temp.path().join("ca.pem");
        let key = temp.path().join("ca.key");
        fs::write(&ca, ca_cert.pem()).unwrap();
        fs::write(&key, ca_key.serialize_pem()).unwrap();
        (temp, db, ca, key)
    }
    fn csr(temp: &Path) -> PathBuf {
        let private = KeyPair::generate().unwrap();
        let params = CertificateParams::new(Vec::<String>::new()).unwrap();
        let pem = params.serialize_request(&private).unwrap().pem().unwrap();
        let path = temp.join(format!("{}.csr", hex::encode(random::<8>())));
        fs::write(&path, pem).unwrap();
        path
    }
    #[test]
    fn one_time_and_same_certificate_recovery() {
        let (temp, db, ca, key) = setup();
        let inv_path = temp.path().join("inv.json");
        let req = temp.path().join("req.json");
        let cert = temp.path().join("cert.pem");
        let id = invite(&db, "phone", 120, &ca, "localhost", &inv_path).unwrap();
        request(&inv_path, &csr(temp.path()), &req).unwrap();
        approve(&db, &ca, &key, &req, &cert).unwrap();
        assert!(approve(&db, &ca, &key, &req, &temp.path().join("dup")).is_err());
        recover(&db, &id, &temp.path().join("recovered")).unwrap();
        assert_eq!(
            fs::read(cert).unwrap(),
            fs::read(temp.path().join("recovered")).unwrap()
        );
    }
    #[test]
    fn wrong_token_and_expiration_fail_closed() {
        let (temp, db, ca, key) = setup();
        let inv_path = temp.path().join("inv.json");
        let req = temp.path().join("req.json");
        let id = invite(&db, "phone", 120, &ca, "localhost", &inv_path).unwrap();
        request(&inv_path, &csr(temp.path()), &req).unwrap();
        let mut modified: Request = serde_json::from_str(&read_text(&req).unwrap()).unwrap();
        modified.token = hex::encode(random::<32>());
        let bad = temp.path().join("badreq");
        fs::write(&bad, serde_json::to_string(&modified).unwrap()).unwrap();
        assert!(approve(&db, &ca, &key, &bad, &temp.path().join("no")).is_err());
        connection(&db)
            .unwrap()
            .execute("UPDATE invitations SET expires_at=0 WHERE id=?1", [id])
            .unwrap();
        assert!(approve(&db, &ca, &key, &req, &temp.path().join("never")).is_err());
    }
    #[test]
    fn corrupt_invite_ca_pin_and_overwrite_refused() {
        let (temp, db, ca, _) = setup();
        let inv_path = temp.path().join("inv.json");
        invite(&db, "phone", 120, &ca, "localhost", &inv_path).unwrap();
        assert!(invite(&db, "phone2", 120, &ca, "localhost", &inv_path).is_err());
        let mut item: Invite = serde_json::from_str(&read_text(&inv_path).unwrap()).unwrap();
        item.ca_sha256 = "00".repeat(32);
        fs::write(&inv_path, serde_json::to_string(&item).unwrap()).unwrap();
        assert!(request(&inv_path, &csr(temp.path()), &temp.path().join("never")).is_err());
    }
}
